contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We pass tokenIds and tokenWeights arrays and provide a MerkleMultiProof struct components
    // Also pass paymentAmount to forward ETH when baseToken == address(0)
    function run(
        uint256[] calldata tokenIds,
        uint256[] calldata tokenWeights,
        bytes32[] calldata proofProof,
        bool[] calldata proofFlags,
        uint256 paymentAmount
    ) public payable {
        require(tokenIds.length == tokenWeights.length, "len");

        // read pre-state
        uint128 beforeVirtualBase = c.virtualBaseTokenReserves();
        uint128 beforeVirtualNft = c.virtualNftReserves();
        address baseToken = c.baseToken();

        // build MerkleMultiProof in calldata-compatible struct for call
        C.MerkleMultiProof memory proof = C.MerkleMultiProof({ proof: new bytes32[](proofProof.length), flags: new bool[](proofFlags.length) });
        for (uint256 i = 0; i < proofProof.length; i++) proof.proof[i] = proofProof[i];
        for (uint256 i = 0; i < proofFlags.length; i++) proof.flags[i] = proofFlags[i];

        // compute weightSum via view by calling sumWeightsAndValidateProof; if it reverts the buy must also revert
        bool sumReverted;
        uint256 weightSum;
        try c.sumWeightsAndValidateProof(tokenIds, tokenWeights, proof) returns (uint256 s) {
            sumReverted = false;
            weightSum = s;
        } catch {
            sumReverted = true;
        }

        // compute expected quote via view
        (uint256 netInputAmount, uint256 feeAmount, uint256 protocolFeeAmount) = c.buyQuote(weightSum);

        // prepare call to buy; if baseToken == address(0) we must send ETH equal to paymentAmount
        if (baseToken == address(0)) {
            require(address(this).balance >= paymentAmount, "fund");
        }

        bool buyReverted;
        try c.buy{value: paymentAmount}(tokenIds, tokenWeights, C.MerkleMultiProof({ proof: proof.proof, flags: proof.flags })) returns (uint256 net, uint256 fee, uint256 protocol) {
            buyReverted = false;
            // nothing else here
        } catch {
            buyReverted = true;
        }

        // read post-state
        uint128 afterVirtualBase = c.virtualBaseTokenReserves();
        uint128 afterVirtualNft = c.virtualNftReserves();

        // General rule (assert): If the weight/proof check did not revert and buy did not revert, then
        // 1) NFTs virtual reserve decreased by exactly weightSum
        // 2) virtualBaseTokenReserves increased by at least (netInputAmount - feeAmount - protocolFeeAmount)
        //    Note: in contract netInputAmount returned by buyQuote already equals inputAmount + fee + protocolFee,
        //    but when buy executes it increases virtualBaseTokenReserves by netInputAmount - feeAmount - protocolFeeAmount
        // We express the rule using only public getters and observed values.

        assert(
            // if sumWeights view reverted then buy must revert (cannot succeed)
            (sumReverted && buyReverted) ||
            // else if sum succeeded then buy did not revert implies both reserve changes hold
            (!sumReverted && !buyReverted &&
                // virtual NFT reserves decreased by weightSum
                (afterVirtualNft + uint128(weightSum) == beforeVirtualNft) &&
                // virtual base reserves increased at least by netInputAmount - fee - protocolFee (all nonnegative)
                // compute expected increment = netInputAmount - feeAmount - protocolFeeAmount
                (afterVirtualBase >= beforeVirtualBase + SafeCast.toUint128(netInputAmount - feeAmount - protocolFeeAmount))
            )
        );
    }

    // receive to accept ETH when test runner funds this contract prior to calling run
    receive() external payable {}
}

