contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // single public entry performing the property-based checks
    // params correspond to initialize(...) arguments and an extra small check value
    function run(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties
    ) public payable {
        // precondition: feeRate must be within declared contract bound to allow successful initialize
        // We don't require anything else; if feeRate is too large, initialize should revert which we capture below
        // Call initialize and capture whether it reverted
        bool reverted;
        try c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read observable state after the attempt
        bool isInitialized = c.initialized();
        address baseTokenRead = c.baseToken();
        address nftRead = c.nft();
        uint128 vbtr = c.virtualBaseTokenReserves();
        uint128 vntr = c.virtualNftReserves();
        uint56 changeFeeRead = c.changeFee();
        uint16 feeRateRead = c.feeRate();
        bytes32 merkleRootRead = c.merkleRoot();
        bool useOracleRead = c.useStolenNftOracle();
        bool payRoyaltiesRead = c.payRoyalties();

        // General rule (single assert):
        // - If initialize reverted then initialized must be false.
        // - If initialize did not revert then initialized must be true and public getters must reflect the provided inputs,
        //   except feeRate which must equal the provided value and also must be <= 5000 (contract enforces this).
        // This assertion is a single boolean combining both branches.
        assert(
            (reverted && isInitialized == false)
            || (
                !reverted
                && isInitialized == true
                && baseTokenRead == _baseToken
                && nftRead == _nft
                && vbtr == _virtualBaseTokenReserves
                && vntr == _virtualNftReserves
                && changeFeeRead == _changeFee
                && feeRateRead == _feeRate
                && merkleRootRead == _merkleRoot
                && useOracleRead == _useStolenNftOracle
                && payRoyaltiesRead == _payRoyalties
            )
        );
    }

    // allow receiving ETH if needed by other interactions
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We test a simple property about buy when the pool uses ETH (baseToken == address(0)) and payRoyalties == false.
    // Preconditions restrict parameters so initialize should succeed (feeRate <= 5000) and msg.value usage is unambiguous.
    function run(
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        uint256[] calldata tokenIds,
        uint256[] calldata tokenWeights,
        uint256 ethForBuy
    ) public payable {
        require(_feeRate <= 5000, "feeRate bound");
        // deploy-time assumptions: use ETH pool (baseToken = address(0)) and no royalties
        // initialize the pool on c as ETH pool
        // Since the checker deploys a fresh c, msg.sender (this contract) is the factory owner for onlyOwner in C; that's acceptable for initialize
        // Call initialize; it must not revert under our preconditions
        c.initialize(address(0), address(0x100), _virtualBaseTokenReserves, _virtualNftReserves, _changeFee, _feeRate, _merkleRoot, false, false);

        // Read reserves before buy
        uint256 beforeVBase = c.virtualBaseTokenReserves();
        uint256 beforeVNft = c.virtualNftReserves();

        // Call buy sending ETH equal to ethForBuy. Ensure this contract has enough balance for the transfer.
        require(address(this).balance >= ethForBuy, "insufficient balance for test");

        bool reverted;
        uint256 netInputAmount;
        uint256 feeAmount;
        uint256 protocolFeeAmount;

        try c.buy{value: ethForBuy}(tokenIds, tokenWeights, C.MerkleMultiProof(new bytes32[](0), new bool[](0))) returns (uint256 n, uint256 f, uint256 p) {
            reverted = false;
            netInputAmount = n;
            feeAmount = f;
            protocolFeeAmount = p;
        } catch {
            reverted = true;
        }

        uint256 afterVBase = c.virtualBaseTokenReserves();
        uint256 afterVNft = c.virtualNftReserves();

        // Single general rule assertion:
        // If buy succeeded (not reverted) then virtualBaseTokenReserves increased by exactly (netInputAmount - feeAmount - protocolFeeAmount)
        // and virtualNftReserves decreased by the sum of tokenWeights. We observe tokenWeights sum locally and compare.
        uint256 sumWeights = 0;
        for (uint i = 0; i < tokenWeights.length; i++) { sumWeights += tokenWeights[i]; }

        assert(
            reverted
            || (
                afterVBase == beforeVBase + (netInputAmount - feeAmount - protocolFeeAmount)
                && afterVNft == beforeVNft - sumWeights
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Single public function taking inputs and performing the test
    function run(
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        uint256[] calldata tokenIds,
        uint256[] calldata tokenWeights
    ) public payable {
        // Preconditions so initialize will succeed and this is an ETH pool with no royalties
        require(_feeRate <= 5000, "feeRate bound");

        // Initialize the pool as ETH-backed and without royalties
        c.initialize(address(0), address(0x100), _virtualBaseTokenReserves, _virtualNftReserves, _changeFee, _feeRate, _merkleRoot, false, false);

        // Read reserves before calling sell
        uint256 beforeVBase = c.virtualBaseTokenReserves();
        uint256 beforeVNft = c.virtualNftReserves();

        // sum weights locally (safe in calldata loop)
        uint256 sumWeights = 0;
        for (uint256 i = 0; i < tokenWeights.length; i++) {
            sumWeights += tokenWeights[i];
        }

        // We must call sell; sell requires transferring NFTs from msg.sender to pool — since this contract is the caller, the call may revert.
        bool reverted;
        uint256 netOutputAmount;
        uint256 feeAmount;
        uint256 protocolFeeAmount;

        try c.sell(tokenIds, tokenWeights, C.MerkleMultiProof(new bytes32[](0), new bool[](0)), new IStolenNftOracle.Message[](0)) returns (uint256 netOut, uint256 fee, uint256 prot) {
            reverted = false;
            netOutputAmount = netOut;
            feeAmount = fee;
            protocolFeeAmount = prot;
        } catch {
            reverted = true;
        }

        uint256 afterVBase = c.virtualBaseTokenReserves();
        uint256 afterVNft = c.virtualNftReserves();

        // General rule asserted: if sell succeeded then virtualBaseTokenReserves decreased by netOutput+fee+protocolFee
        // and virtualNftReserves increased by sumWeights. If it reverted, we accept reverted == true.
        assert(
            reverted || (
                afterVBase == beforeVBase - (netOutputAmount + feeAmount + protocolFeeAmount)
                && afterVNft == beforeVNft + sumWeights
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
