    // Single public function taking inputs and performing the test
    function run(address token, uint256 tokenId) public payable {
        // No special preconditions; token may be any ERC721 contract address

        bool returned;
        bool callReverted = false;
        // Call availableForFlashLoan and capture its boolean result or if it reverted
        try c.availableForFlashLoan(token, tokenId) returns (bool r) {
            returned = r;
        } catch {
            // According to implementation this function should never revert; record that it did
            callReverted = true;
            returned = false;
        }

        // Now try to observe ERC721(token).ownerOf(tokenId). It may revert; catch that.
        bool ownerCheckReverted = false;
        address owner;
        try ERC721(token).ownerOf(tokenId) returns (address o) {
            owner = o;
        } catch {
            ownerCheckReverted = true;
            owner = address(0);
        }

        // The invariant: availableForFlashLoan must not revert; and when ownerOf succeeds, availableForFlashLoan == (owner == address(c)).
        // If ownerOf reverts, availableForFlashLoan must return false (implementation catches and returns false).
        assert(
            // availableForFlashLoan itself did not revert
            !callReverted
            // and if ownerOf succeeded, returned matches ownership equality
            && ( !ownerCheckReverted ? returned == (owner == address(c)) : returned == false )
        );
    }

    receive() external payable {}
}

