            owner = o;
        } catch {
            ownerReverted = true;
            owner = address(0);
        }

        // General rule:
        // - availableForFlashLoan must not revert (implementation should catch ownerOf failures),
        // - if ownerOf returned successfully then avail == (owner == address(c)),
