        if (!reverted) {
            assert(afterVirtualBase >= beforeVirtualBase && afterVirtualNft <= beforeVirtualNft);
        } else {
            // If reverted, the contract should not have mutated these visible reserves.
            assert(afterVirtualBase == beforeVirtualBase && afterVirtualNft == beforeVirtualNft);
