    // single public entry for the property-based test
    function run(uint256[] calldata tokenIds, uint256[] calldata tokenWeights, bytes32[] calldata proof, bool[] calldata flags, uint256 ethAmount) public payable {
        // ensure arrays match lengths
        require(tokenIds.length == tokenWeights.length);
        // prepare MerkleMultiProof struct in calldata style by ABI-encoding then decoding via memory copy
        // We will call sumWeightsAndValidateProof to get weight sum (view) and use buyQuote for expected amounts.

        // Record observables before
        uint256 beforeVirtualNftReserves = c.virtualNftReserves();
        address nftAddr = c.nft();
        uint256 beforeNftBalance = ERC721(nftAddr).balanceOf(address(c));
        uint256 beforePoolEth = address(c).balance;

        // Build MerkleMultiProof in memory to pass to buy
        C.MerkleMultiProof memory mp;
        mp.proof = new bytes32[](proof.length);
        for (uint256 i = 0; i < proof.length; i++) mp.proof[i] = proof[i];
        mp.flags = new bool[](flags.length);
        for (uint256 i = 0; i < flags.length; i++) mp.flags[i] = flags[i];

        // Compute weightSum via public view
        uint256 weightSum;
        bool sumOk = true;
        try c.sumWeightsAndValidateProof(tokenIds, tokenWeights, mp) returns (uint256 s) {
            weightSum = s;
        } catch {
            // If proof invalid, then buy will revert; we assert that buy indeed reverts
            sumOk = false;
        }

        bool reverted = false;
        // Ensure this contract has enough ETH if sending
        if (ethAmount > 0) {
            require(address(this).balance >= ethAmount, "no-eth");
        }

        // Attempt buy; use low-level try/catch to capture revert
        try c.buy{value: ethAmount}(tokenIds, tokenWeights, mp) returns (uint256 netInputAmount, uint256 feeAmount, uint256 protocolFeeAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-state
        uint256 afterVirtualNftReserves = c.virtualNftReserves();
        uint256 afterNftBalance = ERC721(nftAddr).balanceOf(address(c));
        uint256 afterPoolEth = address(c).balance;

        // General rule asserted in single assert:
        // If sumWeightsAndValidateProof previously failed (proof invalid) then buy must have reverted.
        // Otherwise, if buy reverted then at least one of: invalid eth amount or sum-proof failed (we cannot distinguish more here).
        // If buy succeeded (not reverted) then:
        //   - afterVirtualNftReserves == beforeVirtualNftReserves - weightSum
        //   - the pool's nft balance decreased by tokenIds.length
        //   - if baseToken == address(0) then pool ETH balance increased by netInputAmount (we cannot read netInputAmount here after success),
        //     but we can assert that pool ETH balance did not decrease when baseToken is ETH.
        // We encode an assert that covers these observable relationships.

        // Compose the boolean rule
        bool rule;

        // If proof invalid then buy should revert
        if (!sumOk) {
            rule = reverted;
        } else {
            // proof ok: either reverted or succeeded with invariant changes
            if (reverted) {
                // reverted allowed
                rule = true;
            } else {
                // succeeded: check virtualNftReserves decreased by weightSum and NFTs transferred out
                bool virtualDecreased = afterVirtualNftReserves + weightSum == beforeVirtualNftReserves;
                bool nftCountDecreased = beforeNftBalance == afterNftBalance + tokenIds.length;
                // If baseToken is ETH, pool's ETH balance should not be less than before
                bool baseIsEth = c.baseToken() == address(0);
                bool ethNotDecreased = !baseIsEth || afterPoolEth >= beforePoolEth;

                rule = virtualDecreased && nftCountDecreased && ethNotDecreased;
            }
        }

        assert(rule);
    }

    // allow receiving ETH when c sends refunds
    receive() external payable {}
}

