        uint256[] calldata inputTokenWeights,
        bytes32[] calldata inputProofBytes,
        bool[] calldata inputFlags,
        uint256[] calldata outputTokenIds,
        uint256[] calldata outputTokenWeights,
        bytes32[] calldata outputProofBytes,
        bool[] calldata outputFlags,
        uint256 ethForCall
    ) public payable {
        require(inputTokenIds.length == inputTokenWeights.length);
        require(outputTokenIds.length == outputTokenWeights.length);
        if (ethForCall > 0) require(address(this).balance >= ethForCall);

        // Build MerkleMultiProof memory structs
        C.MerkleMultiProof memory inputProof;
        inputProof.proof = new bytes32[](inputProofBytes.length);
        for (uint256 i = 0; i < inputProofBytes.length; i++) inputProof.proof[i] = inputProofBytes[i];
        inputProof.flags = new bool[](inputFlags.length);
        for (uint256 i = 0; i < inputFlags.length; i++) inputProof.flags[i] = inputFlags[i];

        C.MerkleMultiProof memory outputProof;
        outputProof.proof = new bytes32[](outputProofBytes.length);
        for (uint256 i = 0; i < outputProofBytes.length; i++) outputProof.proof[i] = outputProofBytes[i];
        outputProof.flags = new bool[](outputFlags.length);
        for (uint256 i = 0; i < outputFlags.length; i++) outputProof.flags[i] = outputFlags[i];

        // Observe before-state via public getters
        uint128 beforeVirtualNftReserves = c.virtualNftReserves();
        address nftAddr = c.nft();
        uint256 beforePoolNftBalance = ERC721(nftAddr).balanceOf(address(c));
        address baseTokenAddr = c.baseToken();
        uint256 beforePoolEthBalance = address(c).balance;

        // Call view function sumWeightsAndValidateProof for inputs and outputs, capturing revert via try/catch
        bool inputSumOk = true;
        uint256 inputWeightSum = 0;
        try c.sumWeightsAndValidateProof(inputTokenIds, inputTokenWeights, inputProof) returns (uint256 s) {
            inputWeightSum = s;
        } catch {
            inputSumOk = false;
        }

        bool outputSumOk = true;
        uint256 outputWeightSum = 0;
        try c.sumWeightsAndValidateProof(outputTokenIds, outputTokenWeights, outputProof) returns (uint256 s2) {
            outputWeightSum = s2;
        } catch {
            outputSumOk = false;
        }

        // Now perform the change call as a top-level statement and capture whether it reverted.
        bool didRevert;
        try c.change{value: ethForCall}(
            inputTokenIds,
            inputTokenWeights,
            inputProof,
            new IStolenNftOracle.Message[](0),
            outputTokenIds,
            outputTokenWeights,
            outputProof
        ) returns (uint256 feeAmount, uint256 protocolFeeAmount) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        // Read after-state
        uint128 afterVirtualNftReserves = c.virtualNftReserves();
        uint256 afterPoolNftBalance = ERC721(nftAddr).balanceOf(address(c));
        uint256 afterPoolEthBalance = address(c).balance;

        // Single general assert
        assert(
            // If either proof view call failed, we cannot rely on sums => accept either behavior
            (!inputSumOk || !outputSumOk) ? true : (
                // proofs OK: either change reverted or invariants hold after success
                didRevert || (
                    uint256(afterVirtualNftReserves) == uint256(beforeVirtualNftReserves) + inputWeightSum - outputWeightSum
                    && afterPoolNftBalance == beforePoolNftBalance + inputTokenIds.length - outputTokenIds.length
                    && (baseTokenAddr != address(0) || afterPoolEthBalance >= beforePoolEthBalance)
                )
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We will call buy; to allow sending ETH, take ethAmount param and ensure balance
    function run(uint256[] calldata tokenIds, uint256[] calldata tokenWeights, bytes32[] calldata proofNodes, bool[] calldata proofFlags, uint256 ethAmount) public payable {
        // Prepare a MerkleMultiProof struct in calldata style isn't possible directly; pass via memory by decoding
        require(address(this).balance >= ethAmount, "no-eth");

        // Read observable before-state
        uint256 beforeVirtualNft = c.virtualNftReserves();
        uint256 beforeVirtualBase = c.virtualBaseTokenReserves();
        uint256 beforePrice = c.price();

        // Build MerkleMultiProof memory
        C.MerkleMultiProof memory mp;
        mp.proof = new bytes32[](proofNodes.length);
        for (uint i = 0; i < proofNodes.length; i++) mp.proof[i] = proofNodes[i];
        mp.flags = new bool[](proofFlags.length);
        for (uint i = 0; i < proofFlags.length; i++) mp.flags[i] = proofFlags[i];

        // Compute sum of weights locally (this does not access c internals)
        uint256 sumWeights = 0;
        for (uint i = 0; i < tokenWeights.length; i++) sumWeights += tokenWeights[i];

        // Try calling buy and record if it reverted
        bool reverted;
        uint256 netInputAmount;
        uint256 feeAmount;
        uint256 protocolFeeAmount;
        try c.buy{value: ethAmount}(tokenIds, tokenWeights, mp) returns (uint256 n, uint256 f, uint256 p) {
            reverted = false;
            netInputAmount = n;
            feeAmount = f;
            protocolFeeAmount = p;
        } catch {
            reverted = true;
        }

        // After-state reads
        uint256 afterVirtualNft = c.virtualNftReserves();
        uint256 afterVirtualBase = c.virtualBaseTokenReserves();
        uint256 afterPrice = c.price();

        // If buy succeeded then virtualNftReserves must have decreased by exactly sumWeights
        // and virtualBaseTokenReserves must have increased by at least (netInputAmount - feeAmount - protocolFeeAmount)
        // Also price should not decrease if baseToken decimals are consistent: assert that afterPrice >= beforePrice when pool uses base token
        assert(
            reverted || (
                beforeVirtualNft == afterVirtualNft + sumWeights
                && afterVirtualBase >= beforeVirtualBase + (netInputAmount - feeAmount - protocolFeeAmount)
                && (afterPrice >= beforePrice || c.baseToken() != address(0))
            )
        );
    }

    receive() external payable {}
}
